<template><el-form label-position="top"><el-form-item v-for="f in fields" :key="f.id" :label="f.label" :required="f.required"><template v-if="readonly"><div v-if="['image','attachment'].includes(f.type)" class="files"><el-button v-for="id in modelValue[f.id]||[]" :key="id" link type="primary" @click="download(id)">{{files.find(x=>x.id===id)?.name||'查看附件'}}</el-button></div><span v-else>{{display(f)}}</span></template><el-input v-else-if="['text','textarea'].includes(f.type)" :model-value="modelValue[f.id]" :type="f.type==='textarea'?'textarea':'text'" :maxlength="f.type==='textarea'?5000:500" @update:model-value="set(f.id,$event)"/><el-input-number v-else-if="f.type==='number'" :model-value="modelValue[f.id]" @update:model-value="set(f.id,$event)"/><el-date-picker v-else-if="f.type==='date'" :model-value="modelValue[f.id]" type="date" value-format="YYYY-MM-DD" @update:model-value="set(f.id,$event)"/><el-select v-else-if="['select','employee','store'].includes(f.type)" :model-value="modelValue[f.id]" filterable clearable @update:model-value="set(f.id,$event)"><el-option v-for="o in choices(f)" :key="o.value" :label="o.label" :value="o.value"/></el-select><div v-else class="files"><el-upload :show-file-list="false" :auto-upload="false" :accept="f.type==='image'?'image/jpeg,image/png,image/gif,image/webp':'.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.jpg,.jpeg,.png,.gif,.webp'" :on-change="file=>upload(f,file.raw)" :disabled="uploading||!storeId||(modelValue[f.id]||[]).length>=9"><el-button :loading="uploading">{{f.type==='image'?'添加图片':'添加附件'}}</el-button></el-upload><small>每个文件最多20MB，最多9个；先选择申请门店。</small><div v-for="id in modelValue[f.id]||[]" :key="id"><span>{{localFiles[id]?.name||id}}</span><el-button link type="danger" @click="set(f.id,modelValue[f.id].filter(v=>v!==id))">移除</el-button></div></div></el-form-item></el-form></template>
<script setup>
import {ref} from 'vue';import {ElMessage} from 'element-plus';import {customWorkflowApi as api} from '@/api';
const props=defineProps({fields:Array,modelValue:Object,readonly:Boolean,valueLabels:{type:Object,default:()=>({})},files:{type:Array,default:()=>[]},employees:{type:Array,default:()=>[]},stores:{type:Array,default:()=>[]},definitionId:Number,storeId:Number});const emit=defineEmits(['update:modelValue','uploading']);const uploading=ref(false),localFiles=ref({});
const set=(id,v)=>emit('update:modelValue',{...props.modelValue,[id]:v}),choices=f=>f.type==='select'?f.options.map(x=>({label:x,value:x})):f.type==='employee'?props.employees.filter(e=>e.store_id===props.storeId).map(e=>({value:e.id,label:e.name})):props.stores.map(s=>({value:s.id,label:s.store_name}));const display=f=>props.valueLabels[f.id]||choices(f).find(o=>o.value===props.modelValue[f.id])?.label||(props.modelValue[f.id]===0?'0':props.modelValue[f.id])||'—';
async function upload(f,file){if(uploading.value)return;if(file.size>20*1024*1024)return ElMessage.error('单文件最多20MB');uploading.value=true;emit('uploading',true);try{const r=await api.fileStart({definition_id:props.definitionId,store_id:props.storeId,field_id:f.id,name:file.name,bytes:file.size});let index=0;for(let offset=0;offset<file.size;offset+=49152){const bytes=new Uint8Array(await file.slice(offset,offset+49152).arrayBuffer());let binary='';for(const b of bytes)binary+=String.fromCharCode(b);await api.fileChunk(r.upload_id,{index:index++,chunk:btoa(binary)})}const result=await api.fileFinish(r.upload_id);localFiles.value[result.file.id]=result.file;set(f.id,[...(props.modelValue[f.id]||[]),result.file.id])}catch(e){ElMessage.error(e.message)}finally{uploading.value=false;emit('uploading',false)}}
async function download(id){try{const parts=[];let total=1,meta;for(let i=0;i<total;i++){meta=await api.file(id,i);total=meta.total;parts.push(Uint8Array.from(atob(meta.chunk),c=>c.charCodeAt(0)))}const url=URL.createObjectURL(new Blob(parts,{type:meta.mime})),a=document.createElement('a');a.href=url;a.download=meta.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){ElMessage.error(e.message)}}
</script><style scoped>.files{display:grid;gap:8px}.files small{font-size:12px;color:var(--el-text-color-secondary)}.el-select{width:100%}</style>
